	case WASM_OP_I64AND: 
	case WASM_OP_I64OR: 
	case WASM_OP_I64XOR: 
	case WASM_OP_I64SHL: 
	case WASM_OP_I64SHRS: 
	case WASM_OP_I64SHRU: 
	case WASM_OP_I64ROTL: 
