void Compute(OpKernelContext* ctx) override {
  const Tensor& input = ctx->input(0);
  const Tensor& input_min_tensor = ctx->input(1);
  const Tensor& input_max_tensor = ctx->input(2);

  int num_slices = 1;
  if (axis_ > -1) {
    num_slices = input.dim_size(axis_);
  }
  OP_REQUIRES(ctx, input_min_tensor.NumElements() == num_slices,
              errors::InvalidArgument(
                  "input_min_tensor must have as many elements as input on "
                  "the dequantization axis (",
                  axis_, "), got ", input_min_tensor.NumElements(),
                  ", expected ", num_slices));
  OP_REQUIRES(ctx, input_max_tensor.NumElements() == num_slices,
              errors::InvalidArgument(
                  "input_max_tensor must have as many elements as input on "
                  "the dequantization axis (",
                  axis_, "), got ", input_max_tensor.NumElements(),
                  ", expected ", num_slices));

  Tensor* output = nullptr;
  OP_REQUIRES_OK(ctx, ctx->allocate_output(0, input.shape(), &output));
  Tensor float_output =
      need_cast_ ? tensorflow::Tensor(DT_FLOAT, input.shape()) : *output;
  if (num_slices == 1) {
    const float min_range = input_min_tensor.flat<float>()(0);
    const float max_range = input_max_tensor.flat<float>()(0);
    DequantizeTensor(ctx, input, min_range, max_range, &float_output);
  } else {
    OP_REQUIRES(ctx, mode_ != QUANTIZE_MODE_MIN_FIRST,
                errors::Unimplemented("MIN_FIRST mode is not implemented for "
                                      "Dequantize with axis != -1."));

    int64_t pre_dim = 1, post_dim = 1;
    for (int i = 0; i < axis_; ++i) {
      pre_dim *= float_output.dim_size(i);
    }
    for (int i = axis_ + 1; i < float_output.dims(); ++i) {
      post_dim *= float_output.dim_size(i);
    }
    auto input_tensor = input.template bit_casted_shaped<T, 3>(
        {pre_dim, num_slices, post_dim});
    auto output_tensor =
        float_output.flat_inner_outer_dims<float, 3>(axis_ - 1);
    auto min_ranges = input_min_tensor.vec<float>();
    auto max_ranges = input_max_tensor.vec<float>();
    for (int i = 0; i < num_slices; ++i) {
      DequantizeSlice(ctx->eigen_device<Device>(), ctx,
                      input_tensor.template chip<1>(i), min_ranges(i),
                      max_ranges(i), output_tensor.template chip<1>(i));
    }
  }
  if (need_cast_) {
    S* out_ptr = output->flat<S>().data();
    float* in_ptr = float_output.flat<float>().data();
    for (int64_t i = 0; i < float_output.NumElements(); ++i) {
      out_ptr[i] = static_cast<S>(in_ptr[i]);
    }
  }
}

static void *gp_worker_main(void *pvt)
{
    struct gp_thread *t = (struct gp_thread *)pvt;
    struct gp_query *q = NULL;
    char dummy = 0;
    int ret;

    while (!t->pool->shutdown) {

        /* initialize debug client id to 0 until work is scheduled */
        gp_debug_set_conn_id(0);

        /* ======> COND_MUTEX */
        pthread_mutex_lock(&t->cond_mutex);
        while (t->query == NULL) {
            /* wait for next query */
            pthread_cond_wait(&t->cond_wakeup, &t->cond_mutex);
            if (t->pool->shutdown) {
                pthread_exit(NULL);
            }
        }

        /* grab the query off the shared pointer */
        q = t->query;
        t->query = NULL;

        /* <====== COND_MUTEX */
        pthread_mutex_unlock(&t->cond_mutex);

        /* set client id before hndling requests */
        gp_debug_set_conn_id(gp_conn_get_cid(q->conn));

        /* handle the client request */
        GPDEBUGN(3, "[status] Handling query input: %p (%zu)\n", q->buffer,
                 q->buflen);
        gp_handle_query(t->pool, q);
        GPDEBUGN(3 ,"[status] Handling query output: %p (%zu)\n", q->buffer,
                 q->buflen);

        /* now get lock on main queue, to play with the reply list */
        /* ======> POOL LOCK */
        pthread_mutex_lock(&t->pool->lock);

        /* put back query so that dispatcher can send reply */
        q->next = t->pool->reply_list;
        t->pool->reply_list = q;

        /* add us back to the free list but only if we are not
         * shutting down */
        if (!t->pool->shutdown) {
            LIST_DEL(t->pool->busy_list, t);
            LIST_ADD(t->pool->free_list, t);
        }

        /* <====== POOL LOCK */
        pthread_mutex_unlock(&t->pool->lock);

        /* and wake up dispatcher so it will handle it */
        ret = write(t->pool->sig_pipe[1], &dummy, 1);
        if (ret == -1) {
            GPERROR("Failed to signal dispatcher!");
        }
    }

    pthread_exit(NULL);
}

static int hwsim_new_radio_nl(struct sk_buff *msg, struct genl_info *info)
{
	struct hwsim_new_radio_params param = { 0 };
	const char *hwname = NULL;
	int ret;

	param.reg_strict = info->attrs[HWSIM_ATTR_REG_STRICT_REG];
	param.p2p_device = info->attrs[HWSIM_ATTR_SUPPORT_P2P_DEVICE];
	param.channels = channels;
	param.destroy_on_close =
		info->attrs[HWSIM_ATTR_DESTROY_RADIO_ON_CLOSE];

	if (info->attrs[HWSIM_ATTR_CHANNELS])
		param.channels = nla_get_u32(info->attrs[HWSIM_ATTR_CHANNELS]);

	if (info->attrs[HWSIM_ATTR_NO_VIF])
		param.no_vif = true;

	if (info->attrs[HWSIM_ATTR_RADIO_NAME]) {
		hwname = kasprintf(GFP_KERNEL, "%.*s",
				   nla_len(info->attrs[HWSIM_ATTR_RADIO_NAME]),
				   (char *)nla_data(info->attrs[HWSIM_ATTR_RADIO_NAME]));
		if (!hwname)
			return -ENOMEM;
		param.hwname = hwname;
	}

	if (info->attrs[HWSIM_ATTR_USE_CHANCTX])
		param.use_chanctx = true;
	else
		param.use_chanctx = (param.channels > 1);

	if (info->attrs[HWSIM_ATTR_REG_HINT_ALPHA2])
		param.reg_alpha2 =
			nla_data(info->attrs[HWSIM_ATTR_REG_HINT_ALPHA2]);

 	if (info->attrs[HWSIM_ATTR_REG_CUSTOM_REG]) {
 		u32 idx = nla_get_u32(info->attrs[HWSIM_ATTR_REG_CUSTOM_REG]);

		if (idx >= ARRAY_SIZE(hwsim_world_regdom_custom))
 			return -EINVAL;
 		param.regd = hwsim_world_regdom_custom[idx];
 	}

	ret = mac80211_hwsim_new_radio(info, &param);
	kfree(hwname);
	return ret;
}

static int cdrom_ioctl_media_changed(struct cdrom_device_info *cdi,
		unsigned long arg)
{
	struct cdrom_changer_info *info;
	int ret;

	cd_dbg(CD_DO_IOCTL, "entering CDROM_MEDIA_CHANGED\n");

	if (!CDROM_CAN(CDC_MEDIA_CHANGED))
		return -ENOSYS;

	/* cannot select disc or select current disc */
 	if (!CDROM_CAN(CDC_SELECT_DISC) || arg == CDSL_CURRENT)
 		return media_changed(cdi, 1);

	if ((unsigned int)arg >= cdi->capacity)
 		return -EINVAL;

 	info = kmalloc(sizeof(*info), GFP_KERNEL);
	if (!info)
		return -ENOMEM;

	ret = cdrom_read_mech_status(cdi, info);
	if (!ret)
		ret = info->slots[arg].change;
	kfree(info);
	return ret;
}

