icmp_print(netdissect_options *ndo, const u_char *bp, u_int plen, const u_char *bp2,
           int fragmented)
{
	char *cp;
	const struct icmp *dp;
        const struct icmp_ext_t *ext_dp;
	const struct ip *ip;
	const char *str, *fmt;
	const struct ip *oip;
	const struct udphdr *ouh;
        const uint8_t *obj_tptr;
        uint32_t raw_label;
        const u_char *snapend_save;
	const struct icmp_mpls_ext_object_header_t *icmp_mpls_ext_object_header;
	u_int hlen, dport, mtu, obj_tlen, obj_class_num, obj_ctype;
	char buf[MAXHOSTNAMELEN + 100];
	struct cksum_vec vec[1];

	dp = (const struct icmp *)bp;
        ext_dp = (const struct icmp_ext_t *)bp;
	ip = (const struct ip *)bp2;
	str = buf;

	ND_TCHECK(dp->icmp_code);
	switch (dp->icmp_type) {

	case ICMP_ECHO:
	case ICMP_ECHOREPLY:
		ND_TCHECK(dp->icmp_seq);
		(void)snprintf(buf, sizeof(buf), "echo %s, id %u, seq %u",
                               dp->icmp_type == ICMP_ECHO ?
                               "request" : "reply",
                               EXTRACT_16BITS(&dp->icmp_id),
                               EXTRACT_16BITS(&dp->icmp_seq));
		break;

	case ICMP_UNREACH:
		ND_TCHECK(dp->icmp_ip.ip_dst);
		switch (dp->icmp_code) {

		case ICMP_UNREACH_PROTOCOL:
			ND_TCHECK(dp->icmp_ip.ip_p);
			(void)snprintf(buf, sizeof(buf),
			    "%s protocol %d unreachable",
			    ipaddr_string(ndo, &dp->icmp_ip.ip_dst),
			    dp->icmp_ip.ip_p);
			break;

		case ICMP_UNREACH_PORT:
			ND_TCHECK(dp->icmp_ip.ip_p);
			oip = &dp->icmp_ip;
			hlen = IP_HL(oip) * 4;
			ouh = (const struct udphdr *)(((const u_char *)oip) + hlen);
			ND_TCHECK(ouh->uh_dport);
			dport = EXTRACT_16BITS(&ouh->uh_dport);
			switch (oip->ip_p) {

			case IPPROTO_TCP:
				(void)snprintf(buf, sizeof(buf),
					"%s tcp port %s unreachable",
					ipaddr_string(ndo, &oip->ip_dst),
					tcpport_string(ndo, dport));
				break;

			case IPPROTO_UDP:
				(void)snprintf(buf, sizeof(buf),
					"%s udp port %s unreachable",
					ipaddr_string(ndo, &oip->ip_dst),
					udpport_string(ndo, dport));
				break;

			default:
				(void)snprintf(buf, sizeof(buf),
					"%s protocol %d port %d unreachable",
					ipaddr_string(ndo, &oip->ip_dst),
					oip->ip_p, dport);
				break;
			}
			break;

		case ICMP_UNREACH_NEEDFRAG:
		    {
			register const struct mtu_discovery *mp;
			mp = (const struct mtu_discovery *)(const u_char *)&dp->icmp_void;
			mtu = EXTRACT_16BITS(&mp->nexthopmtu);
			if (mtu) {
				(void)snprintf(buf, sizeof(buf),
				    "%s unreachable - need to frag (mtu %d)",
				    ipaddr_string(ndo, &dp->icmp_ip.ip_dst), mtu);
			} else {
				(void)snprintf(buf, sizeof(buf),
				    "%s unreachable - need to frag",
				    ipaddr_string(ndo, &dp->icmp_ip.ip_dst));
			}
		    }
			break;

		default:
			fmt = tok2str(unreach2str, "#%d %%s unreachable",
			    dp->icmp_code);
			(void)snprintf(buf, sizeof(buf), fmt,
			    ipaddr_string(ndo, &dp->icmp_ip.ip_dst));
			break;
		}
		break;

	case ICMP_REDIRECT:
		ND_TCHECK(dp->icmp_ip.ip_dst);
		fmt = tok2str(type2str, "redirect-#%d %%s to net %%s",
		    dp->icmp_code);
		(void)snprintf(buf, sizeof(buf), fmt,
		    ipaddr_string(ndo, &dp->icmp_ip.ip_dst),
		    ipaddr_string(ndo, &dp->icmp_gwaddr));
		break;

	case ICMP_ROUTERADVERT:
	    {
		register const struct ih_rdiscovery *ihp;
		register const struct id_rdiscovery *idp;
		u_int lifetime, num, size;

		(void)snprintf(buf, sizeof(buf), "router advertisement");
		cp = buf + strlen(buf);

		ihp = (const struct ih_rdiscovery *)&dp->icmp_void;
		ND_TCHECK(*ihp);
		(void)strncpy(cp, " lifetime ", sizeof(buf) - (cp - buf));
		cp = buf + strlen(buf);
		lifetime = EXTRACT_16BITS(&ihp->ird_lifetime);
		if (lifetime < 60) {
			(void)snprintf(cp, sizeof(buf) - (cp - buf), "%u",
			    lifetime);
		} else if (lifetime < 60 * 60) {
			(void)snprintf(cp, sizeof(buf) - (cp - buf), "%u:%02u",
			    lifetime / 60, lifetime % 60);
		} else {
			(void)snprintf(cp, sizeof(buf) - (cp - buf),
			    "%u:%02u:%02u",
			    lifetime / 3600,
			    (lifetime % 3600) / 60,
			    lifetime % 60);
		}
		cp = buf + strlen(buf);

		num = ihp->ird_addrnum;
		(void)snprintf(cp, sizeof(buf) - (cp - buf), " %d:", num);
		cp = buf + strlen(buf);

		size = ihp->ird_addrsiz;
		if (size != 2) {
			(void)snprintf(cp, sizeof(buf) - (cp - buf),
			    " [size %d]", size);
			break;
		}
		idp = (const struct id_rdiscovery *)&dp->icmp_data;
		while (num-- > 0) {
			ND_TCHECK(*idp);
			(void)snprintf(cp, sizeof(buf) - (cp - buf), " {%s %u}",
			    ipaddr_string(ndo, &idp->ird_addr),
			    EXTRACT_32BITS(&idp->ird_pref));
			cp = buf + strlen(buf);
			++idp;
		}
	    }
		break;

	case ICMP_TIMXCEED:
		ND_TCHECK(dp->icmp_ip.ip_dst);
		switch (dp->icmp_code) {

		case ICMP_TIMXCEED_INTRANS:
			str = "time exceeded in-transit";
			break;

		case ICMP_TIMXCEED_REASS:
			str = "ip reassembly time exceeded";
			break;

		default:
			(void)snprintf(buf, sizeof(buf), "time exceeded-#%d",
			    dp->icmp_code);
			break;
		}
		break;

	case ICMP_PARAMPROB:
		if (dp->icmp_code)
			(void)snprintf(buf, sizeof(buf),
			    "parameter problem - code %d", dp->icmp_code);
		else {
			ND_TCHECK(dp->icmp_pptr);
			(void)snprintf(buf, sizeof(buf),
			    "parameter problem - octet %d", dp->icmp_pptr);
		}
		break;

	case ICMP_MASKREPLY:
		ND_TCHECK(dp->icmp_mask);
		(void)snprintf(buf, sizeof(buf), "address mask is 0x%08x",
		    EXTRACT_32BITS(&dp->icmp_mask));
		break;

	case ICMP_TSTAMP:
		ND_TCHECK(dp->icmp_seq);
		(void)snprintf(buf, sizeof(buf),
		    "time stamp query id %u seq %u",
		    EXTRACT_16BITS(&dp->icmp_id),
		    EXTRACT_16BITS(&dp->icmp_seq));
		break;

	case ICMP_TSTAMPREPLY:
		ND_TCHECK(dp->icmp_ttime);
		(void)snprintf(buf, sizeof(buf),
		    "time stamp reply id %u seq %u: org %s",
                               EXTRACT_16BITS(&dp->icmp_id),
                               EXTRACT_16BITS(&dp->icmp_seq),
                               icmp_tstamp_print(EXTRACT_32BITS(&dp->icmp_otime)));

                (void)snprintf(buf+strlen(buf),sizeof(buf)-strlen(buf),", recv %s",
                         icmp_tstamp_print(EXTRACT_32BITS(&dp->icmp_rtime)));
                (void)snprintf(buf+strlen(buf),sizeof(buf)-strlen(buf),", xmit %s",
                         icmp_tstamp_print(EXTRACT_32BITS(&dp->icmp_ttime)));
                break;

	default:
		str = tok2str(icmp2str, "type-#%d", dp->icmp_type);
		break;
	}
	ND_PRINT((ndo, "ICMP %s, length %u", str, plen));
	if (ndo->ndo_vflag && !fragmented) { /* don't attempt checksumming if this is a frag */
		uint16_t sum, icmp_sum;

		if (ND_TTEST2(*bp, plen)) {
			vec[0].ptr = (const uint8_t *)(const void *)dp;
			vec[0].len = plen;
			sum = in_cksum(vec, 1);
			if (sum != 0) {
				icmp_sum = EXTRACT_16BITS(&dp->icmp_cksum);
				ND_PRINT((ndo, " (wrong icmp cksum %x (->%x)!)",
					     icmp_sum,
					     in_cksum_shouldbe(icmp_sum, sum)));
			}
		}
	}

        /*
         * print the remnants of the IP packet.
         * save the snaplength as this may get overidden in the IP printer.
         */
	if (ndo->ndo_vflag >= 1 && ICMP_ERRTYPE(dp->icmp_type)) {
		bp += 8;
		ND_PRINT((ndo, "\n\t"));
		ip = (const struct ip *)bp;
                snapend_save = ndo->ndo_snapend;
		ip_print(ndo, bp, EXTRACT_16BITS(&ip->ip_len));
                ndo->ndo_snapend = snapend_save;
	}

        /*
         * Attempt to decode the MPLS extensions only for some ICMP types.
         */
        if (ndo->ndo_vflag >= 1 && plen > ICMP_EXTD_MINLEN && ICMP_MPLS_EXT_TYPE(dp->icmp_type)) {

            ND_TCHECK(*ext_dp);

            /*
             * Check first if the mpls extension header shows a non-zero length.
             * If the length field is not set then silently verify the checksum
              * to check if an extension header is present. This is expedient,
              * however not all implementations set the length field proper.
              */
            if (!ext_dp->icmp_length) {
                 vec[0].ptr = (const uint8_t *)(const void *)&ext_dp->icmp_ext_version_res;
                 vec[0].len = plen - ICMP_EXTD_MINLEN;
                 if (in_cksum(vec, 1)) {
                    return;
                }
            }

            ND_PRINT((ndo, "\n\tMPLS extension v%u",
                   ICMP_MPLS_EXT_EXTRACT_VERSION(*(ext_dp->icmp_ext_version_res))));

            /*
             * Sanity checking of the header.
             */
            if (ICMP_MPLS_EXT_EXTRACT_VERSION(*(ext_dp->icmp_ext_version_res)) !=
                ICMP_MPLS_EXT_VERSION) {
                ND_PRINT((ndo, " packet not supported"));
                return;
             }

             hlen = plen - ICMP_EXTD_MINLEN;
            vec[0].ptr = (const uint8_t *)(const void *)&ext_dp->icmp_ext_version_res;
            vec[0].len = hlen;
            ND_PRINT((ndo, ", checksum 0x%04x (%scorrect), length %u",
                   EXTRACT_16BITS(ext_dp->icmp_ext_checksum),
                   in_cksum(vec, 1) ? "in" : "",
                   hlen));

             hlen -= 4; /* subtract common header size */
             obj_tptr = (const uint8_t *)ext_dp->icmp_ext_data;

            while (hlen > sizeof(struct icmp_mpls_ext_object_header_t)) {

                icmp_mpls_ext_object_header = (const struct icmp_mpls_ext_object_header_t *)obj_tptr;
                ND_TCHECK(*icmp_mpls_ext_object_header);
                obj_tlen = EXTRACT_16BITS(icmp_mpls_ext_object_header->length);
                obj_class_num = icmp_mpls_ext_object_header->class_num;
                obj_ctype = icmp_mpls_ext_object_header->ctype;
                obj_tptr += sizeof(struct icmp_mpls_ext_object_header_t);

                ND_PRINT((ndo, "\n\t  %s Object (%u), Class-Type: %u, length %u",
                       tok2str(icmp_mpls_ext_obj_values,"unknown",obj_class_num),
                       obj_class_num,
                       obj_ctype,
                       obj_tlen));

                hlen-=sizeof(struct icmp_mpls_ext_object_header_t); /* length field includes tlv header */

                /* infinite loop protection */
                if ((obj_class_num == 0) ||
                    (obj_tlen < sizeof(struct icmp_mpls_ext_object_header_t))) {
                    return;
                }
                obj_tlen-=sizeof(struct icmp_mpls_ext_object_header_t);

                switch (obj_class_num) {
                case 1:
                    switch(obj_ctype) {
                    case 1:
                        ND_TCHECK2(*obj_tptr, 4);
                        raw_label = EXTRACT_32BITS(obj_tptr);
                        ND_PRINT((ndo, "\n\t    label %u, exp %u", MPLS_LABEL(raw_label), MPLS_EXP(raw_label)));
                        if (MPLS_STACK(raw_label))
                            ND_PRINT((ndo, ", [S]"));
                        ND_PRINT((ndo, ", ttl %u", MPLS_TTL(raw_label)));
                        break;
                    default:
                        print_unknown_data(ndo, obj_tptr, "\n\t    ", obj_tlen);
                    }
                    break;

               /*
                *  FIXME those are the defined objects that lack a decoder
                *  you are welcome to contribute code ;-)
                */
                case 2:
                default:
                    print_unknown_data(ndo, obj_tptr, "\n\t    ", obj_tlen);
                    break;
                }
                if (hlen < obj_tlen)
                    break;
                hlen -= obj_tlen;
                obj_tptr += obj_tlen;
            }
        }

	return;
trunc:
	ND_PRINT((ndo, "[|icmp]"));
}

stl_update_connects_remove_1(stl_file *stl, int facet_num) {
  int j;

  if (stl->error) return;
  /* Update list of connected edges */
  j = ((stl->neighbors_start[facet_num].neighbor[0] == -1) +
       (stl->neighbors_start[facet_num].neighbor[1] == -1) +
       (stl->neighbors_start[facet_num].neighbor[2] == -1));
  if(j == 0) {		       /* Facet has 3 neighbors */
    stl->stats.connected_facets_3_edge -= 1;
  } else if(j == 1) {	     /* Facet has 2 neighbors */
    stl->stats.connected_facets_2_edge -= 1;
  } else if(j == 2) {	     /* Facet has 1 neighbor  */
    stl->stats.connected_facets_1_edge -= 1;
  }
}

MagickExport MagickBooleanType SetImageProfile(Image *image,const char *name,
  const StringInfo *profile,ExceptionInfo *exception)
{
  char
    key[MaxTextExtent],
    property[MaxTextExtent];

  MagickBooleanType
    status;

  assert(image != (Image *) NULL);
  assert(image->signature == MagickSignature);
  if (image->debug != MagickFalse)
    (void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",image->filename);
  if (image->profiles == (SplayTreeInfo *) NULL)
    image->profiles=NewSplayTree(CompareSplayTreeString,RelinquishMagickMemory,
      DestroyProfile);
  (void) CopyMagickString(key,name,MaxTextExtent);
  status=AddValueToSplayTree((SplayTreeInfo *) image->profiles,
    ConstantString(key),CloneStringInfo(profile));
  if ((status != MagickFalse) &&
      ((LocaleCompare(name,"iptc") == 0) || (LocaleCompare(name,"8bim") == 0)))
    (void) GetProfilesFromResourceBlock(image,profile,exception);
  /*
    Inject profile into image properties.
  */
  (void) FormatLocaleString(property,MaxTextExtent,"%s:sans",name);
  (void) GetImageProperty(image,property,exception);
  return(status);
}

void DISOpticalFlowImpl::calc(InputArray I0, InputArray I1, InputOutputArray flow)
{
    CV_Assert(!I0.empty() && I0.depth() == CV_8U && I0.channels() == 1);
    CV_Assert(!I1.empty() && I1.depth() == CV_8U && I1.channels() == 1);
    CV_Assert(I0.sameSize(I1));
    CV_Assert(I0.isContinuous());
    CV_Assert(I1.isContinuous());

    CV_OCL_RUN(flow.isUMat() &&
               (patch_size == 8) && (use_spatial_propagation == true),
               ocl_calc(I0, I1, flow));

    Mat I0Mat = I0.getMat();
    Mat I1Mat = I1.getMat();
    bool use_input_flow = false;
    if (flow.sameSize(I0) && flow.depth() == CV_32F && flow.channels() == 2)
        use_input_flow = true;
    else
        flow.create(I1Mat.size(), CV_32FC2);
    Mat flowMat = flow.getMat();
    coarsest_scale = min((int)(log(max(I0Mat.cols, I0Mat.rows) / (4.0 * patch_size)) / log(2.0) + 0.5), /* Original code serach for maximal movement of width/4 */
                         (int)(log(min(I0Mat.cols, I0Mat.rows) / patch_size) / log(2.0)));              /* Deepest pyramid level greater or equal than patch*/
    int num_stripes = getNumThreads();

    prepareBuffers(I0Mat, I1Mat, flowMat, use_input_flow);
    Ux[coarsest_scale].setTo(0.0f);
    Uy[coarsest_scale].setTo(0.0f);

    for (int i = coarsest_scale; i >= finest_scale; i--)
    {
        w = I0s[i].cols;
        h = I0s[i].rows;
        ws = 1 + (w - patch_size) / patch_stride;
        hs = 1 + (h - patch_size) / patch_stride;

        precomputeStructureTensor(I0xx_buf, I0yy_buf, I0xy_buf, I0x_buf, I0y_buf, I0xs[i], I0ys[i]);
        if (use_spatial_propagation)
        {
            /* Use a fixed number of stripes regardless the number of threads to make inverse search
             * with spatial propagation reproducible
             */
            parallel_for_(Range(0, 8), PatchInverseSearch_ParBody(*this, 8, hs, Sx, Sy, Ux[i], Uy[i], I0s[i],
                                                                  I1s_ext[i], I0xs[i], I0ys[i], 2, i));
        }
        else
        {
            parallel_for_(Range(0, num_stripes),
                          PatchInverseSearch_ParBody(*this, num_stripes, hs, Sx, Sy, Ux[i], Uy[i], I0s[i], I1s_ext[i],
                                                     I0xs[i], I0ys[i], 1, i));
        }

        parallel_for_(Range(0, num_stripes),
                      Densification_ParBody(*this, num_stripes, I0s[i].rows, Ux[i], Uy[i], Sx, Sy, I0s[i], I1s[i]));
        if (variational_refinement_iter > 0)
            variational_refinement_processors[i]->calcUV(I0s[i], I1s[i], Ux[i], Uy[i]);

        if (i > finest_scale)
        {
            resize(Ux[i], Ux[i - 1], Ux[i - 1].size());
            resize(Uy[i], Uy[i - 1], Uy[i - 1].size());
            Ux[i - 1] *= 2;
            Uy[i - 1] *= 2;
        }
    }
    Mat uxy[] = {Ux[finest_scale], Uy[finest_scale]};
    merge(uxy, 2, U);
    resize(U, flowMat, flowMat.size());
    flowMat *= 1 << finest_scale;
}

_bdf_parse_glyphs( char*          line,
                   unsigned long  linelen,
                   unsigned long  lineno,
                   void*          call_data,
                   void*          client_data )
{
  int                c, mask_index;
  char*              s;
  unsigned char*     bp;
  unsigned long      i, slen, nibbles;

  _bdf_parse_t*      p;
  bdf_glyph_t*       glyph;
  bdf_font_t*        font;

  FT_Memory          memory;
  FT_Error           error = BDF_Err_Ok;

  FT_UNUSED( call_data );
  FT_UNUSED( lineno );        /* only used in debug mode */


  p = (_bdf_parse_t *)client_data;

  font   = p->font;
  memory = font->memory;

  /* Check for a comment. */
  if ( ft_memcmp( line, "COMMENT", 7 ) == 0 )
  {
    linelen -= 7;

    s = line + 7;
    if ( *s != 0 )
    {
      s++;
      linelen--;
    }
    error = _bdf_add_comment( p->font, s, linelen );
    goto Exit;
  }

  /* The very first thing expected is the number of glyphs. */
  if ( !( p->flags & _BDF_GLYPHS ) )
  {
    if ( ft_memcmp( line, "CHARS", 5 ) != 0 )
    {
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG1, lineno, "CHARS" ));
      error = BDF_Err_Missing_Chars_Field;
      goto Exit;
    }

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;
    p->cnt = font->glyphs_size = _bdf_atoul( p->list.field[1], 0, 10 );

    /* Make sure the number of glyphs is non-zero. */
    if ( p->cnt == 0 )
      font->glyphs_size = 64;

    /* Limit ourselves to 1,114,112 glyphs in the font (this is the */
    /* number of code points available in Unicode).                 */
    if ( p->cnt >= 0x110000UL )
    {
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG5, lineno, "CHARS" ));
      error = BDF_Err_Invalid_Argument;
      goto Exit;
    }

    if ( FT_NEW_ARRAY( font->glyphs, font->glyphs_size ) )
      goto Exit;

    p->flags |= _BDF_GLYPHS;

    goto Exit;
  }

  /* Check for the ENDFONT field. */
  if ( ft_memcmp( line, "ENDFONT", 7 ) == 0 )
  {
    /* Sort the glyphs by encoding. */
    ft_qsort( (char *)font->glyphs,
              font->glyphs_used,
              sizeof ( bdf_glyph_t ),
              by_encoding );

    p->flags &= ~_BDF_START;

    goto Exit;
  }

  /* Check for the ENDCHAR field. */
  if ( ft_memcmp( line, "ENDCHAR", 7 ) == 0 )
  {
    p->glyph_enc = 0;
    p->flags    &= ~_BDF_GLYPH_BITS;

    goto Exit;
  }

  /* Check whether a glyph is being scanned but should be */
  /* ignored because it is an unencoded glyph.            */
  if ( ( p->flags & _BDF_GLYPH )     &&
       p->glyph_enc            == -1 &&
       p->opts->keep_unencoded == 0  )
    goto Exit;

  /* Check for the STARTCHAR field. */
  if ( ft_memcmp( line, "STARTCHAR", 9 ) == 0 )
  {
    /* Set the character name in the parse info first until the */
    /* encoding can be checked for an unencoded character.      */
    FT_FREE( p->glyph_name );

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;

    _bdf_list_shift( &p->list, 1 );

    s = _bdf_list_join( &p->list, ' ', &slen );

    if ( !s )
    {
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG8, lineno, "STARTCHAR" ));
      error = BDF_Err_Invalid_File_Format;
      goto Exit;
    }

    if ( FT_NEW_ARRAY( p->glyph_name, slen + 1 ) )
      goto Exit;

    FT_MEM_COPY( p->glyph_name, s, slen + 1 );

    p->flags |= _BDF_GLYPH;

    FT_TRACE4(( DBGMSG1, lineno, s ));

    goto Exit;
  }

  /* Check for the ENCODING field. */
  if ( ft_memcmp( line, "ENCODING", 8 ) == 0 )
  {
    if ( !( p->flags & _BDF_GLYPH ) )
    {
      /* Missing STARTCHAR field. */
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG1, lineno, "STARTCHAR" ));
      error = BDF_Err_Missing_Startchar_Field;
      goto Exit;
    }

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;

    p->glyph_enc = _bdf_atol( p->list.field[1], 0, 10 );

    /* Normalize negative encoding values.  The specification only */
    /* allows -1, but we can be more generous here.                */
    if ( p->glyph_enc < -1 )
      p->glyph_enc = -1;

    /* Check for alternative encoding format. */
     if ( p->glyph_enc == -1 && p->list.used > 2 )
       p->glyph_enc = _bdf_atol( p->list.field[2], 0, 10 );

     FT_TRACE4(( DBGMSG2, p->glyph_enc ));

     /* Check that the encoding is in the Unicode range because  */
                                 sizeof ( unsigned long ) * 32 )
    {
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG5, lineno, "ENCODING" ));
      error = BDF_Err_Invalid_File_Format;
      goto Exit;
    }

    /* Check whether this encoding has already been encountered. */
    /* If it has then change it to unencoded so it gets added if */
    /* indicated.                                                */
    if ( p->glyph_enc >= 0 )
    {
      if ( _bdf_glyph_modified( p->have, p->glyph_enc ) )
      {
        /* Emit a message saying a glyph has been moved to the */
        /* unencoded area.                                     */
        FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG12,
                    p->glyph_enc, p->glyph_name ));
        p->glyph_enc = -1;
        font->modified = 1;
      }
      else
        _bdf_set_glyph_modified( p->have, p->glyph_enc );
    }

    if ( p->glyph_enc >= 0 )
    {
      /* Make sure there are enough glyphs allocated in case the */
      /* number of characters happen to be wrong.                */
      if ( font->glyphs_used == font->glyphs_size )
      {
        if ( FT_RENEW_ARRAY( font->glyphs,
                             font->glyphs_size,
                             font->glyphs_size + 64 ) )
          goto Exit;

        font->glyphs_size += 64;
      }

      glyph           = font->glyphs + font->glyphs_used++;
      glyph->name     = p->glyph_name;
      glyph->encoding = p->glyph_enc;

      /* Reset the initial glyph info. */
      p->glyph_name = 0;
    }
    else
    {
      /* Unencoded glyph.  Check whether it should */
      /* be added or not.                          */
      if ( p->opts->keep_unencoded != 0 )
      {
        /* Allocate the next unencoded glyph. */
        if ( font->unencoded_used == font->unencoded_size )
        {
          if ( FT_RENEW_ARRAY( font->unencoded ,
                               font->unencoded_size,
                               font->unencoded_size + 4 ) )
            goto Exit;

          font->unencoded_size += 4;
        }

        glyph           = font->unencoded + font->unencoded_used;
        glyph->name     = p->glyph_name;
        glyph->encoding = font->unencoded_used++;
      }
      else
        /* Free up the glyph name if the unencoded shouldn't be */
        /* kept.                                                */
        FT_FREE( p->glyph_name );

      p->glyph_name = 0;
    }

    /* Clear the flags that might be added when width and height are */
    /* checked for consistency.                                      */
    p->flags &= ~( _BDF_GLYPH_WIDTH_CHECK | _BDF_GLYPH_HEIGHT_CHECK );

    p->flags |= _BDF_ENCODING;

    goto Exit;
  }

  /* Point at the glyph being constructed. */
  if ( p->glyph_enc == -1 )
    glyph = font->unencoded + ( font->unencoded_used - 1 );
  else
    glyph = font->glyphs + ( font->glyphs_used - 1 );

  /* Check whether a bitmap is being constructed. */
  if ( p->flags & _BDF_BITMAP )
  {
    /* If there are more rows than are specified in the glyph metrics, */
    /* ignore the remaining lines.                                     */
    if ( p->row >= (unsigned long)glyph->bbx.height )
    {
      if ( !( p->flags & _BDF_GLYPH_HEIGHT_CHECK ) )
      {
        FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG13, glyph->encoding ));
        p->flags |= _BDF_GLYPH_HEIGHT_CHECK;
        font->modified = 1;
      }

      goto Exit;
    }

    /* Only collect the number of nibbles indicated by the glyph     */
    /* metrics.  If there are more columns, they are simply ignored. */
    nibbles = glyph->bpr << 1;
    bp      = glyph->bitmap + p->row * glyph->bpr;

    for ( i = 0; i < nibbles; i++ )
    {
      c = line[i];
      if ( !sbitset( hdigits, c ) )
        break;
      *bp = (FT_Byte)( ( *bp << 4 ) + a2i[c] );
      if ( i + 1 < nibbles && ( i & 1 ) )
        *++bp = 0;
    }

    /* If any line has not enough columns,            */
    /* indicate they have been padded with zero bits. */
    if ( i < nibbles                            &&
         !( p->flags & _BDF_GLYPH_WIDTH_CHECK ) )
    {
      FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG16, glyph->encoding ));
      p->flags       |= _BDF_GLYPH_WIDTH_CHECK;
      font->modified  = 1;
    }

    /* Remove possible garbage at the right. */
    mask_index = ( glyph->bbx.width * p->font->bpp ) & 7;
    if ( glyph->bbx.width )
      *bp &= nibble_mask[mask_index];

    /* If any line has extra columns, indicate they have been removed. */
    if ( i == nibbles                           &&
         sbitset( hdigits, line[nibbles] )      &&
         !( p->flags & _BDF_GLYPH_WIDTH_CHECK ) )
    {
      FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG14, glyph->encoding ));
      p->flags       |= _BDF_GLYPH_WIDTH_CHECK;
      font->modified  = 1;
    }

    p->row++;
    goto Exit;
  }

  /* Expect the SWIDTH (scalable width) field next. */
  if ( ft_memcmp( line, "SWIDTH", 6 ) == 0 )
  {
    if ( !( p->flags & _BDF_ENCODING ) )
      goto Missing_Encoding;

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;

    glyph->swidth = (unsigned short)_bdf_atoul( p->list.field[1], 0, 10 );
    p->flags |= _BDF_SWIDTH;

    goto Exit;
  }

  /* Expect the DWIDTH (scalable width) field next. */
  if ( ft_memcmp( line, "DWIDTH", 6 ) == 0 )
  {
    if ( !( p->flags & _BDF_ENCODING ) )
      goto Missing_Encoding;

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;

    glyph->dwidth = (unsigned short)_bdf_atoul( p->list.field[1], 0, 10 );

    if ( !( p->flags & _BDF_SWIDTH ) )
    {
      /* Missing SWIDTH field.  Emit an auto correction message and set */
      /* the scalable width from the device width.                      */
      FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG9, lineno ));

      glyph->swidth = (unsigned short)FT_MulDiv(
                        glyph->dwidth, 72000L,
                        (FT_Long)( font->point_size *
                                   font->resolution_x ) );
    }

    p->flags |= _BDF_DWIDTH;
    goto Exit;
  }

  /* Expect the BBX field next. */
  if ( ft_memcmp( line, "BBX", 3 ) == 0 )
  {
    if ( !( p->flags & _BDF_ENCODING ) )
      goto Missing_Encoding;

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;

    glyph->bbx.width    = _bdf_atos( p->list.field[1], 0, 10 );
    glyph->bbx.height   = _bdf_atos( p->list.field[2], 0, 10 );
    glyph->bbx.x_offset = _bdf_atos( p->list.field[3], 0, 10 );
    glyph->bbx.y_offset = _bdf_atos( p->list.field[4], 0, 10 );

    /* Generate the ascent and descent of the character. */
    glyph->bbx.ascent  = (short)( glyph->bbx.height + glyph->bbx.y_offset );
    glyph->bbx.descent = (short)( -glyph->bbx.y_offset );

    /* Determine the overall font bounding box as the characters are */
    /* loaded so corrections can be done later if indicated.         */
    p->maxas    = (short)FT_MAX( glyph->bbx.ascent, p->maxas );
    p->maxds    = (short)FT_MAX( glyph->bbx.descent, p->maxds );

    p->rbearing = (short)( glyph->bbx.width + glyph->bbx.x_offset );

    p->maxrb    = (short)FT_MAX( p->rbearing, p->maxrb );
    p->minlb    = (short)FT_MIN( glyph->bbx.x_offset, p->minlb );
    p->maxlb    = (short)FT_MAX( glyph->bbx.x_offset, p->maxlb );

    if ( !( p->flags & _BDF_DWIDTH ) )
    {
      /* Missing DWIDTH field.  Emit an auto correction message and set */
      /* the device width to the glyph width.                           */
      FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG10, lineno ));
      glyph->dwidth = glyph->bbx.width;
    }

    /* If the BDF_CORRECT_METRICS flag is set, then adjust the SWIDTH */
    /* value if necessary.                                            */
    if ( p->opts->correct_metrics != 0 )
    {
      /* Determine the point size of the glyph. */
      unsigned short  sw = (unsigned short)FT_MulDiv(
                             glyph->dwidth, 72000L,
                             (FT_Long)( font->point_size *
                                        font->resolution_x ) );


      if ( sw != glyph->swidth )
      {
        glyph->swidth = sw;

        if ( p->glyph_enc == -1 )
          _bdf_set_glyph_modified( font->umod,
                                   font->unencoded_used - 1 );
        else
          _bdf_set_glyph_modified( font->nmod, glyph->encoding );

        p->flags       |= _BDF_SWIDTH_ADJ;
        font->modified  = 1;
      }
    }

    p->flags |= _BDF_BBX;
    goto Exit;
  }

  /* And finally, gather up the bitmap. */
  if ( ft_memcmp( line, "BITMAP", 6 ) == 0 )
  {
    unsigned long  bitmap_size;


    if ( !( p->flags & _BDF_BBX ) )
    {
      /* Missing BBX field. */
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG1, lineno, "BBX" ));
      error = BDF_Err_Missing_Bbx_Field;
      goto Exit;
    }

    /* Allocate enough space for the bitmap. */
    glyph->bpr = ( glyph->bbx.width * p->font->bpp + 7 ) >> 3;

    bitmap_size = glyph->bpr * glyph->bbx.height;
    if ( glyph->bpr > 0xFFFFU || bitmap_size > 0xFFFFU )
    {
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG4, lineno ));
      error = BDF_Err_Bbx_Too_Big;
      goto Exit;
    }
    else
      glyph->bytes = (unsigned short)bitmap_size;

    if ( FT_NEW_ARRAY( glyph->bitmap, glyph->bytes ) )
      goto Exit;

    p->row    = 0;
    p->flags |= _BDF_BITMAP;

    goto Exit;
  }

  FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG9, lineno ));
  error = BDF_Err_Invalid_File_Format;
  goto Exit;

Missing_Encoding:
  /* Missing ENCODING field. */
  FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG1, lineno, "ENCODING" ));
  error = BDF_Err_Missing_Encoding_Field;

Exit:
  if ( error && ( p->flags & _BDF_GLYPH ) )
    FT_FREE( p->glyph_name );

  return error;
}

bool TextAutosizer::isAutosizingCluster(const RenderBlock* renderer)
{
    ASSERT(isAutosizingContainer(renderer));

    return renderer->isRenderView()
        || renderer->isFloating()
        || renderer->isOutOfFlowPositioned()
        || renderer->isTableCell()
        || renderer->isTableCaption()
        || renderer->isFlexibleBoxIncludingDeprecated()
        || renderer->hasColumns()
        || renderer->style()->overflowX() != OVISIBLE
        || renderer->style()->overflowY() != OVISIBLE
        || renderer->containingBlock()->isHorizontalWritingMode() != renderer->isHorizontalWritingMode();
}

